+      border: 1px solid var(--panel-border);
+      border-radius: 24px;
+      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
+      padding: 32px;
+      backdrop-filter: blur(14px);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.75rem, 3vw, 2.3rem);
+      line-height: 1.1;
+    }
+
+    p {
+      margin: 0 0 28px;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      font-weight: 600;
+      color: #f8fafc;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--field-border);
+      background: var(--field);
+      color: var(--text);
+      border-radius: 14px;
+      padding: 14px 16px;
+      font: inherit;
+      outline: none;
+      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
+    }
+
+    input::placeholder {
+      color: #64748b;
+    }
+
+    input:focus {
+      border-color: var(--accent);
+      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.16);
+    }
+
+    input[aria-invalid="true"] {
+      border-color: var(--error);
+      box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.12);
+    }
+
+    .helper-text {
+      color: var(--muted);
+      font-size: 0.92rem;
+      line-height: 1.45;
+    }
+
+    .error-message {
+      min-height: 1.1em;
+      color: var(--error);
+      font-size: 0.92rem;
+      line-height: 1.35;
+    }
+
+    button {
+      margin-top: 6px;
+      border: 0;
+      border-radius: 14px;
+      padding: 14px 18px;
+      font: inherit;
+      font-weight: 700;
+      color: white;
+      background: linear-gradient(135deg, var(--accent-strong), #2563eb);
+      cursor: pointer;
+      box-shadow: 0 12px 30px rgba(37, 99, 235, 0.28);
+      transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+      filter: brightness(1.03);
+      box-shadow: 0 16px 34px rgba(37, 99, 235, 0.34);
+    }
+
+    button:active {
+      transform: translateY(0);
+    }
+
+    @media (max-width: 520px) {
+      .support-card {
+        padding: 22px;
+        border-radius: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="support-card">
+    <h1>Contact support</h1>
+    <p>Send us a message and we’ll get back to you as soon as possible.</p>
+
+    <form id="contactForm" novalidate>
+      <div class="form-field">
+        <label for="fullName">Full name</label>
+        <input id="fullName" name="fullName" type="text" placeholder="Jane Doe" autocomplete="name" required />
+        <div class="error-message" id="fullNameError" aria-live="polite"></div>
+      </div>
+
+      <div class="form-field">
+        <label for="emailAddress">Email address</label>
+        <input id="emailAddress" name="emailAddress" type="email" placeholder="jane@example.com" autocomplete="email" required />
+        <div class="error-message" id="emailAddressError" aria-live="polite"></div>
+      </div>
+
+      <div class="form-field">
+        <label for="phoneNumber">Phone number</label>
+        <input
+          id="phoneNumber"
+          name="phoneNumber"
+          type="tel"
+          placeholder="+1 555 123 4567"
+          autocomplete="tel"
+          aria-describedby="phoneHelper phoneNumberError"
+        />
+        <div class="helper-text" id="phoneHelper">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</div>
+        <div class="error-message" id="phoneNumberError" aria-live="polite"></div>
+      </div>
+
+      <button type="submit">Send message</button>
+    </form>
+  </main>
+
+  <script>
+    const form = document.getElementById('contactForm');
+    const fullName = document.getElementById('fullName');
+    const emailAddress = document.getElementById('emailAddress');
+    const phoneNumber = document.getElementById('phoneNumber');
+
+    const validators = {
+      fullName(value) {
+        if (!value.trim()) return 'Full name is required.';
+        if (value.trim().length < 2) return 'Please enter your full name.';
+        return '';
+      },
+      emailAddress(value) {
+        if (!value.trim()) return 'Email address is required.';
+        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        return emailPattern.test(value.trim()) ? '' : 'Please enter a valid email address.';
+      },
+      phoneNumber(value) {
+        if (!value.trim()) return '';
+        const phonePattern = /^[+]?[\d\s().-]{7,}$/;
+        return phonePattern.test(value.trim()) ? '' : 'Please use a valid phone number format.';
+      }
+    };
+
+    function setFieldState(input, errorText) {
+      const errorElement = document.getElementById(`${input.id}Error`);
+      const hasError = Boolean(errorText);
+
+      input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
+      errorElement.textContent = errorText;
+    }
+
+    function validateField(input) {
+      const errorText = validators[input.id](input.value);
+      setFieldState(input, errorText);
+      return !errorText;
+    }
+
+    [fullName, emailAddress, phoneNumber].forEach((input) => {
+      input.addEventListener('blur', () => validateField(input));
+      input.addEventListener('input', () => {
+        if (input.getAttribute('aria-invalid') === 'true') {
+          validateField(input);
+        }
+      });
+    });
+
+    form.addEventListener('submit', (event) => {
+      const isFullNameValid = validateField(fullName);
+      const isEmailValid = validateField(emailAddress);
+      const isPhoneValid = validateField(phoneNumber);
+
+      if (!isFullNameValid || !isEmailValid || !isPhoneValid) {
+        event.preventDefault();
+        return;
+      }
+
+      event.preventDefault();
+      form.reset();
+      [fullName, emailAddress, phoneNumber].forEach((input) => setFieldState(input, ''));
+      alert('Thanks! Your message has been prepared for submission.');
+    });
+  </script>
+</body>
+</html>
*** End Patch
